INSERT INTO question_bank
(category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at)
VALUES
('Java 基础', '1-3 年', 'Java,IO,BIO,NIO,AIO', 3, 'BIO、NIO、AIO 有什么区别？', 'BIO 是阻塞 I/O，每个连接通常占用一个线程，连接多时线程开销大；NIO 基于 Channel、Buffer 和 Selector 的多路复用，一个线程可以管理多个连接，适合高并发；AIO 是异步 I/O，数据复制完成后由系统回调通知，线程不必等待。Java 21 的虚拟线程可以用同步写法获得较好的并发能力。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Java 基础', '1-3 年', 'Java,NIO,Channel,Buffer,Selector', 3, 'Java NIO 的核心组件有哪些？', '核心是 Channel、Buffer 和 Selector。Channel 表示可读写的通道，Buffer 负责数据缓冲，Selector 通过事件就绪通知让一个线程管理多个 Channel。NIO 是面向缓冲区的非阻塞 I/O，通常配合多路复用处理高并发连接。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Java 基础', '校招', 'Java,IO,字节流,字符流', 2, 'Java IO 流如何分类？字节流和字符流有什么区别？', '按处理单位分为字节流和字符流，按方向分为输入流和输出流，按功能分为节点流和处理流。字节流以 InputStream/OutputStream 为父类，适合图片、文件等二进制数据；字符流以 Reader/Writer 为父类，按字符编码处理文本，适合文本读写。转换流可以完成字节流和字符流之间的转换。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Java 基础', '校招', '网络,TCP,UDP', 2, 'TCP 和 UDP 有什么区别？', 'TCP 面向连接、可靠传输，提供确认、重传、排序和流量控制，适合对数据完整性要求高的场景；UDP 无连接、不保证可靠和顺序，开销小、延迟低，适合视频、语音、游戏和广播。TCP 像打电话，UDP 像寄明信片。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Java 基础', '1-3 年', 'Java,Lambda,函数式接口', 2, '什么是 Lambda 表达式？它和匿名内部类有什么区别？', 'Lambda 是匿名函数的语法糖，本质是函数式接口的实例，常用于把行为作为参数传递，例如 Stream 和 Comparator。它比匿名内部类语法更简洁；匿名内部类可以实现任意接口或抽象类，而 Lambda 只能对应一个函数式接口。Lambda 中的 this 指向外层对象，匿名内部类的 this 指向自身实例。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Java 基础', '1-3 年', 'Java,函数式接口,Consumer,Supplier,Function,Predicate', 2, 'Java 中常见的函数式接口有哪些？', '常见的有 Consumer（消费一个参数，无返回值）、Supplier（无参数，返回一个值）、Function（一个参数，返回一个值）、Predicate（一个参数，返回 boolean）、Runnable（无参数无返回值）和 Callable（无参数有返回值）。它们可以用 Lambda 或方法引用简化实现，是 Stream 和并发编程的基础。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Java 基础', '1-3 年', 'Tomcat,调优,线程池,虚拟线程', 3, 'Tomcat 有哪些常见优化手段？', '可以从线程池、连接数、I/O 模式和 JVM 入手。常见配置包括 max-connections、accept-count、threads.max、threads.min-spare；Tomcat 默认使用 NIO，Linux 下通常无需改成 NIO2。还可以优化 JVM 参数、静态资源缓存、日志和会话管理；JDK 21 可以开启虚拟线程来提升阻塞式请求的并发能力。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Java 基础', '1-3 年', 'Java,equals,hashCode,HashMap', 2, '为什么重写 equals 时必须重写 hashCode？', 'equals 判断两个对象逻辑上是否相等，hashCode 用于哈希表定位。Java 约定相等的对象必须返回相同的 hashCode，否则 HashMap、HashSet 会出现两个相等对象落在不同桶、无法去重或查找失败的问题。重写时两者要基于同一组关键字段，并保证对象未修改时 hashCode 稳定。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Java 基础', '校招', 'Java,Comparable,Comparator,排序', 2, 'Comparable 和 Comparator 有什么区别？', 'Comparable 是对象自身实现的自然排序接口，重写 compareTo，排序规则固定在类内部；Comparator 是外部比较器，重写 compare，可以在不修改类的情况下定义多种排序规则。Collections.sort 和 Stream.sorted 都支持两者，实际项目更常用 Comparator 配合 Lambda 做灵活排序。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Java 基础', '1-3 年', 'Java,try-with-resources,AutoCloseable,异常', 2, 'try-with-resources 的原理是什么？', 'try-with-resources 要求资源实现 AutoCloseable，编译器会在 try 块结束时自动调用 close，效果类似在 finally 中关闭资源。多个资源按声明的逆序关闭；即使 try 块抛异常，close 也会执行。若 close 也抛异常，会被作为抑制异常（suppressed）附加到主异常上。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Java 基础', '1-3 年', 'Java,接口,默认方法,静态方法,Java8', 2, '接口中的默认方法和静态方法有什么作用？', 'Java 8 允许接口定义 default 方法和 static 方法。default 方法提供默认实现，让接口新增方法时不必修改所有实现类，常用于集合框架演进；static 方法属于接口本身，通过接口名调用，适合放工具方法。默认方法解决不了多继承状态问题，接口仍然不能有实例字段。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Java 并发', '1-3 年', 'Java,并发,悲观锁,乐观锁,CAS', 3, '悲观锁和乐观锁有什么区别？', '悲观锁假设并发冲突经常发生，访问数据前先加锁，例如数据库 select ... for update、synchronized；乐观锁假设冲突较少，先修改再校验版本号或 CAS，失败后重试。悲观锁阻塞等待、一致性更强，乐观锁开销小但冲突多时重试成本高。选型要看冲突概率和临界区大小。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('基础算法', '1-3 年', '加密算法,对称加密,非对称加密,哈希,签名', 3, '常见的加密算法有哪些？如何分类？', '常见分为对称加密（DES、AES、SM4）、非对称加密（RSA、ECDSA、SM2）、哈希摘要（MD5、SHA-2、SHA-3、SM3）和电子签名。对称加密加解密快，适合大量数据；非对称加密用于密钥交换和签名；哈希摘要用于完整性校验和密码存储；签名结合私钥和摘要防止篡改。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('基础算法', '1-3 年', '加密,对称加密,非对称加密,哈希摘要', 3, '对称加密、非对称加密和哈希摘要有什么区别？', '对称加密加密和解密使用同一把密钥，速度快，但密钥需要安全分发；非对称加密使用公钥加密、私钥解密，公钥可公开，速度较慢，常用于密钥交换和签名；哈希摘要不可逆，把任意数据映射为固定长度摘要，用于完整性校验和密码存储，不能用来还原原文。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('基础算法', '1-3 年', '电子签名,数字签名,摘要,公钥,私钥', 3, '电子签名是如何防止数据被篡改的？', '发送方先对消息计算摘要，再用自己的私钥加密摘要形成签名，消息和签名一起发送。接收方用发送方公钥解密签名得到摘要，并对收到的消息重新计算摘要，两者一致说明消息未被篡改且确实来自私钥持有者。签名解决完整性和身份认证，不负责保密，保密还需要加密。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('基础算法', '1-3 年', '密码存储,BCrypt,加盐,哈希', 3, '用户密码应该如何存储？', '不能明文存储，也不建议只做一次 MD5/SHA 摘要，因为简单密码容易被彩虹表反查。正确做法是使用 bcrypt、scrypt、Argon2 等带盐、可调成本的慢哈希算法，每个用户使用独立随机盐，并支持成本因子升级。登录时校验哈希而不是解密，数据库泄露时能显著增加破解成本。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('基础算法', '1-3 年', '对称加密,DES,AES,SM4', 3, 'DES、AES 和 SM4 有什么区别？', '三者都是对称加密算法。DES 使用 56 位密钥，强度不足，已不推荐；AES 支持 128、192、256 位密钥，性能好、生态成熟，是国际通用标准；SM4 是中国商用密码标准，分组长度和密钥长度都是 128 位，在国内政务和金融场景使用较多。新项目优先选择 AES 或符合合规要求的 SM4。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('基础算法', '1-3 年', '非对称加密,RSA,ECDSA,SM2', 3, 'RSA、ECDSA 和 SM2 有什么区别？', '三者都是非对称加密/签名算法。RSA 基于大数分解，常用密钥长度 2048 位以上；ECDSA 基于椭圆曲线离散对数，密钥更短、效率更高；SM2 是中国商用密码椭圆曲线算法，密钥长度 256 位，国内合规场景常用。ECDSA 与 SM2 原理相近，但曲线参数和标准不同，不能混用。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('基础算法', '校招', '排序,时间复杂度,稳定性', 2, '常见的排序算法有哪些？时间复杂度如何？', '比较排序有冒泡、选择、插入、归并、快速和堆排序。冒泡、选择、插入平均 O(n²)；归并、快速、堆排序平均 O(n log n)。归并稳定但需要 O(n) 额外空间；快速平均最快但最坏 O(n²)，空间 O(log n)；堆排序原地但不稳定。计数、桶、基数排序是非比较排序，特定条件下可达到 O(n)。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('基础算法', '校招', '排序,稳定性', 2, '什么是稳定排序和不稳定排序？', '稳定排序指排序前后，值相等的元素相对顺序保持不变；不稳定排序则可能改变它们的相对顺序。例如冒泡、插入、归并是稳定的；选择、快速、堆排序通常不稳定。稳定性在按多个字段排序时很重要，例如先按分数排序再按姓名排序，稳定排序能保留前一次的顺序。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('基础算法', '校招', '排序,冒泡排序', 2, '冒泡排序的实现思路是什么？', '把数组分成已排序和未排序两部分，每一轮从未排序区从左到右比较相邻元素，逆序就交换，一轮结束后最大值会冒到未排序区最右侧。重复 n-1 轮，已排序区逐渐扩大。最好情况 O(n)，平均和最坏 O(n²)，空间 O(1)，是稳定排序。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('基础算法', '校招', '排序,选择排序', 2, '选择排序的实现思路是什么？', '每一轮从未排序区选出最小或最大元素，放到已排序区的边界，已排序区逐渐扩大，直到全部有序。无论数据是否有序，比较次数都接近 n(n-1)/2，时间复杂度 O(n²)，空间 O(1)。交换次数较少，但跨位置交换会破坏相等元素的相对顺序，因此不稳定。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('基础算法', '校招', '排序,插入排序', 2, '插入排序的实现思路是什么？', '把数组分成已排序和未排序两部分，每次取未排序区最左侧元素，在已排序区从右向左找到合适位置并插入，后面的元素依次后移。数据基本有序时接近 O(n)，平均和最坏 O(n²)，空间 O(1)，是稳定排序。适合小规模或有序度高的数据。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('基础算法', '1-3 年', '排序,归并排序,分治', 3, '归并排序的实现思路是什么？', '采用分治思想：把数组从中间不断二分，直到子数组只剩一个元素；再把相邻的有序子数组合并成更大的有序数组，最终得到整体有序。时间复杂度稳定为 O(n log n)，需要 O(n) 额外空间，是稳定排序。适合链表排序和对稳定性有要求的场景。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('基础算法', '1-3 年', '排序,快速排序,分区,优化', 3, '快速排序的实现思路是什么？如何优化？', '选择一个基准值，通过分区把比基准小的元素放到左边、大的放到右边，基准落到最终位置，再递归处理左右区间。平均 O(n log n)，最坏 O(n²)，空间 O(log n)，不稳定。优化包括随机选基准或三数取中、小区间改用插入排序、三路分区处理大量重复元素、尾递归优化。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('基础算法', '1-3 年', '排序,堆排序,大顶堆', 3, '堆排序的实现思路是什么？', '先把数组构建成大顶堆，堆顶是最大值；把堆顶与末尾元素交换，最大值就排好序，然后对剩余部分继续下潜调整，重复直到全部有序。建堆 O(n)，每次调整 O(log n)，总时间 O(n log n)，空间 O(1)，不稳定。适合对空间要求严格且不需要稳定性的场景。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('基础算法', '校招', '查找,二分查找,有序数组', 2, '二分查找的实现思路和适用条件是什么？', '二分查找要求数据有序且支持随机访问。用左右指针维护搜索区间，每次取中间元素与目标比较，相等则返回，目标较小则收缩右边界，较大则收缩左边界，直到区间为空。时间复杂度 O(log n)，空间 O(1)。边界条件要统一区间开闭，避免死循环和漏查。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('基础算法', '1-3 年', '算法,回溯,递归,剪枝', 3, '什么是回溯算法？剪枝起什么作用？', '回溯是一种试探性搜索：递归地做出选择，记录当前状态，如果发现当前路径不可能得到解就撤销选择，回到上一步尝试其他分支。典型问题是全排列、组合、N 皇后、数独。剪枝是在递归前用条件判断提前排除不可能的分支，减少搜索树规模，提高效率。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('基础算法', '校招', '算法,字符串,双指针,反转', 1, '如何反转一个字符串或字符数组？', '使用双指针，i 指向起始位置，j 指向末尾，交换两个字符后 i 右移、j 左移，直到相遇。时间复杂度 O(n)，空间 O(1)。Java 中字符串不可变，需要先转成 char[] 或 StringBuilder；如果要求反转单词顺序，可以先整体反转再逐个单词反转。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Web 基础', '校招', 'HTTP,HTTPS,TLS,证书', 2, 'HTTP 和 HTTPS 有什么区别？', 'HTTP 是明文传输，默认端口 80；HTTPS 在 HTTP 和 TCP 之间加入 TLS/SSL，对传输内容加密，默认端口 443，并通过证书验证服务器身份。HTTPS 能防止窃听、篡改和冒充，但需要证书和额外的加解密开销。现代 Web 应默认使用 HTTPS。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Web 基础', '校招', 'HTTP,GET,POST,RESTful', 2, 'GET 和 POST 请求有什么区别？', 'GET 参数放在 URL 中，长度受 URL 和服务器限制，适合查询，能被缓存和收藏；POST 参数放在请求体中，适合提交和修改数据，相对不那么容易暴露在地址栏。两者本质上都是 HTTP 方法，安全性取决于是否使用 HTTPS，不能简单说 POST 一定安全。RESTful 中还会使用 PUT、DELETE 等方法。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Web 基础', '校招', 'HTTP,状态码', 2, '常见 HTTP 状态码有哪些？', '状态码分 1xx 信息、2xx 成功、3xx 重定向、4xx 客户端错误、5xx 服务端错误。常见有 200 成功、201 已创建、204 无内容、301/302 重定向、304 未修改、400 参数错误、401 未认证、403 无权限、404 资源不存在、405 方法不允许、429 请求过多、500 服务器内部错误、502 网关错误、503 服务不可用。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Web 基础', '校招', 'Web,转发,重定向,HTTP', 2, '转发和重定向有什么区别？', '转发是服务器内部把请求交给另一个资源处理，浏览器只发起一次请求，地址栏不变，可以共享 request 域数据；重定向是服务器返回 3xx 和 Location，浏览器再发起一次新请求，地址栏会变化，不能共享原 request 数据。前后端分离项目中页面跳转通常由前端路由完成，接口层更多使用重定向做登录跳转或兼容旧地址。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Web 基础', '1-3 年', 'Web,Cookie,Session,会话跟踪', 2, 'Cookie 和 Session 的会话跟踪原理是什么？有什么区别？', 'Cookie 是客户端存储，服务器通过 Set-Cookie 下发，浏览器后续请求通过 Cookie 头自动携带；Session 是服务端会话对象，服务器把 Session ID 通过名为 JSESSIONID 的 Cookie 发给浏览器，后续根据 ID 找到对应 Session。Cookie 存储在客户端、容量小、可被用户操作；Session 存储在服务端、相对安全，但集群下需要共享，常见方案是 Redis 集中存储。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Web 基础', '1-3 年', '网络,TCP,三次握手,四次挥手', 3, 'TCP 三次握手和四次挥手的过程是什么？', '三次握手：客户端发送 SYN，服务端回复 SYN+ACK，客户端再发送 ACK，连接建立。四次挥手：主动关闭方发送 FIN，对方回复 ACK；对方数据发送完后再发送 FIN，主动方回复 ACK，连接关闭。握手确认双方的发送和接收能力，挥手因为 TCP 全双工，两个方向需要分别关闭。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Web 基础', '1-3 年', '网络,TCP,握手,序列号', 3, '为什么 TCP 需要三次握手，而不能是两次？', '两次握手无法确认客户端的接收能力和服务端的发送能力，还可能让历史重复的 SYN 建立无效连接。三次握手让双方都确认自己和对方的发送、接收能力正常，并同步初始序列号，避免旧连接请求造成资源浪费。四次挥手则是因为 TCP 是全双工，两个方向要独立关闭。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('MySQL 和 MyBatis', '校招', 'MySQL,CHAR,VARCHAR,数据类型', 2, 'CHAR 和 VARCHAR 有什么区别？如何选择？', 'CHAR 是定长字符串，长度固定，不足部分用空格填充，读取时通常去掉尾部空格；VARCHAR 是变长字符串，只占用实际长度加长度前缀的空间。CHAR 适合长度固定的字段，如手机号、身份证号、状态码；VARCHAR 适合用户名、备注、地址等长度变化大的字段。VARCHAR 更省空间，但更新变长时可能产生页分裂。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('MySQL 和 MyBatis', '1-3 年', 'MySQL,索引,联合索引,最左前缀', 3, '创建索引应该遵循哪些原则？', '优先给数据量大、查询频繁的表建索引；给 where、order by、group by 中高频出现的列建索引；选择区分度高的列，唯一列建唯一索引；长字符串可以用前缀索引；多用联合索引并遵循最左前缀，尽量覆盖查询避免回表；索引不是越多越好，过多会增加写入和维护成本。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('MySQL 和 MyBatis', '1-3 年', 'MySQL,EXPLAIN,执行计划,索引优化', 3, '如何用 EXPLAIN 分析 SQL 的执行计划？', '在 SQL 前加 EXPLAIN 查看执行计划，重点看 key 是否命中索引、key_len 使用了多少索引列、type 的访问类型、rows 预估扫描行数以及 Extra 是否出现 Using filesort、Using temporary、Using index 等信息。type 从好到坏大致是 system、const、eq_ref、ref、range、index、ALL，要尽量避免 ALL 全表扫描。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('MySQL 和 MyBatis', '1-3 年', 'MySQL,事务,隔离级别,MVCC,幻读', 3, 'MySQL 的事务隔离级别有哪些？分别解决什么问题？', '常见四级：读未提交会脏读、不可重复读、幻读；读已提交解决脏读，但仍有不可重复读和幻读；可重复读解决脏读和不可重复读，MySQL InnoDB 默认使用它，并通过 MVCC 和间隙锁减少幻读；串行化全部解决但并发性能最差。隔离级别越高一致性越强，吞吐通常越低，要按业务取舍。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('MySQL 和 MyBatis', '1-3 年', 'MyBatis,执行流程,SqlSession,Executor', 3, 'MyBatis 的总体执行流程是怎样的？', '先加载 mybatis-config.xml 和 Mapper 映射，构建 SqlSessionFactory；由工厂创建 SqlSession；SqlSession 通过 Executor 执行 Mapper 方法对应的 MappedStatement；Executor 处理参数映射、SQL 生成、缓存和 JDBC 调用，最后把结果集映射为 Java 对象。SqlSession 不是线程安全的，通常交给 Spring 管理生命周期。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('MySQL 和 MyBatis', '1-3 年', 'MyBatis,resultType,resultMap,结果映射', 2, 'MyBatis 中 resultType 和 resultMap 有什么区别？', 'resultType 直接指定返回类型，要求列名和属性名能按规则对应，适合简单映射；resultMap 通过 id、result、association、collection 等标签定义列与属性的映射，能处理字段名不一致、一对一、一对多和嵌套查询等复杂关系。简单查询用 resultType 更简洁，复杂对象用 resultMap 更清晰。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('MySQL 和 MyBatis', '1-3 年', 'MyBatis,Mapper,传参,Param', 2, 'MyBatis Mapper 方法如何传参？', '单个简单参数可以直接用参数名或任意名字引用；多个参数建议用 @Param 指定名称，否则在 XML 中要用 param1、param2 或 arg0、arg1；传入对象或 Map 时可以直接使用属性名或 key；集合和数组参数通常配合 foreach 使用。推荐统一使用 @Param，避免编译参数名丢失导致映射失败。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('MySQL 和 MyBatis', '1-3 年', 'MyBatis,XML,映射文件,动态SQL', 2, 'MyBatis XML 映射文件有哪些常用配置？', '常见有 mapper namespace、resultMap、sql 片段、select/insert/update/delete、parameterType、resultType、useGeneratedKeys、foreach、if/choose 动态 SQL、cache 二级缓存配置。全局配置还包括 environments、mappers、typeAliases、settings 等。namespace 必须和 Mapper 接口全限定名一致。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('MySQL 和 MyBatis', '1-3 年', 'MyBatis,缓存,一级缓存,二级缓存', 3, 'MyBatis 一级缓存和二级缓存有什么区别？', '一级缓存是 SqlSession 级别，默认开启且无法关闭，同一个 SqlSession 中相同查询会命中缓存；二级缓存是 Mapper namespace 级别，默认关闭，需要配置 cache 标签，能跨 SqlSession 共享，但要求数据提交后才可见。缓存会带来脏读风险，更新频繁或一致性要求高的数据要谨慎使用，分布式环境更常用 Redis。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('MySQL 和 MyBatis', '1-3 年', 'MyBatis-Plus,BaseMapper,Wrapper,分页', 2, 'MyBatis-Plus 有哪些常用 API？', '常用有 BaseMapper 的 insert、deleteById、updateById、selectById、selectList、selectPage；条件构造器 QueryWrapper、LambdaQueryWrapper、UpdateWrapper；IService 和 ServiceImpl 的 save、update、remove、list、page；分页插件 PaginationInnerInterceptor；还有逻辑删除、自动填充、乐观锁插件等。Lambda 写法能避免字段名硬编码。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Spring Boot 和 Spring', '1-3 年', 'Spring,Bean,线程安全,单例', 3, 'Spring 容器中的 Bean 是线程安全的吗？', 'Spring 默认 Bean 是单例的，容器本身不保证线程安全。如果 Bean 没有可变成员变量，像常见的 Controller、Service、Mapper，通常可以认为是线程安全的；如果存在共享可变状态，多线程并发访问就会出现问题。解决办法是避免共享状态、使用局部变量、加锁，或把作用域改成 prototype。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Spring Boot 和 Spring', '校招', 'Spring,Bean,作用域,Scope', 2, 'Spring Bean 有哪些作用域？如何设置？', '常见作用域有 singleton（默认单例）、prototype（每次获取新实例）、request（每个请求一个实例）、session（每个会话一个实例）、application（整个 ServletContext 一个实例）和 websocket。可以用 @Scope 注解或 XML 的 scope 属性设置。Web 作用域只在 Web 环境中有效，多数业务 Bean 使用默认单例。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Spring Boot 和 Spring', '1-3 年', 'Spring,Bean,初始化,Lazy', 3, 'Spring 单例 Bean 什么时候初始化？如何延迟初始化？', '单例 Bean 默认在容器启动时实例化并完成依赖注入和初始化，属于饿汉式；可以通过 @Lazy 注解或 XML 的 lazy-init 延迟到第一次使用时创建。prototype Bean 每次获取时都会创建新实例。延迟初始化能缩短启动时间，但会把创建开销和错误推迟到运行期，核心 Bean 一般不建议延迟。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Spring Boot 和 Spring', '1-3 年', 'Spring,事务,AOP,Transactional', 3, 'Spring 事务的底层实现原理是什么？', 'Spring 事务本质上是 AOP：通过代理拦截带 @Transactional 的方法，方法执行前由 PlatformTransactionManager 开启事务，执行成功提交，抛出符合条件的异常则回滚。事务管理器负责连接绑定、隔离级别、超时和传播行为。因为依赖代理，同类内部方法自调用、非 public 方法、异常被吞掉等情况会导致事务失效。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Spring Boot 和 Spring', '1-3 年', 'Spring,注解,Component,Autowired,AOP', 2, 'Spring 常用注解有哪些？如何分类？', '声明 Bean 的有 @Component、@Service、@Repository、@Controller；依赖注入有 @Autowired、@Qualifier、@Resource；作用域有 @Scope；配置类有 @Configuration、@ComponentScan、@Bean；AOP 有 @Aspect、@Pointcut、@Before、@After、@Around、@AfterReturning、@AfterThrowing；事务有 @Transactional；Web 有 @RequestMapping、@RestController 等。回答时按类别说更清晰。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Spring Boot 和 Spring', '1-3 年', 'SpringMVC,DispatcherServlet,HandlerMapping,HandlerAdapter', 3, 'Spring MVC 的核心组件有哪些？', '核心是 DispatcherServlet，负责接收请求并调度；HandlerMapping 根据 URL 找到处理器；HandlerAdapter 负责调用处理器并处理参数和返回值；Handler 就是 Controller 中的方法；ViewResolver 把逻辑视图名解析为具体视图。前后端分离项目通常返回 JSON，ViewResolver 的作用弱化，但 DispatcherServlet、HandlerMapping、HandlerAdapter 仍然是核心。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Spring Boot 和 Spring', '1-3 年', 'SpringMVC,拦截器,登录校验,Token', 3, 'Spring MVC 拦截器如何实现登录校验？', '定义类实现 HandlerInterceptor，在 preHandle 中从请求头或 Cookie 获取 Token，校验通过返回 true，否则返回 false 并写出 401；再通过 WebMvcConfigurer 的 addInterceptors 注册拦截器，配置拦截路径和排除路径，例如登录、注册、静态资源。拦截器适合做 Spring MVC 层的统一登录校验和日志，最终权限仍要在业务层或 Security 中校验。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Spring Boot 和 Spring', '校招', 'SpringMVC,注解,RequestMapping,RequestBody', 2, 'Spring MVC 常用注解有哪些？', '常用有 @RequestMapping、@GetMapping、@PostMapping、@PutMapping、@DeleteMapping 映射请求；@RequestBody 接收 JSON 请求体；@ResponseBody 把返回值写成响应体；@RequestParam 绑定查询参数；@PathVariable 绑定路径变量；@RequestHeader 获取请求头；@RestController 等于 @Controller 加 @ResponseBody；@ControllerAdvice 和 @ExceptionHandler 做全局异常处理。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Spring Boot 和 Spring', '1-3 年', 'SpringBoot,配置,优先级,profile', 3, 'Spring Boot 配置的优先级是怎样的？', 'Spring Boot 配置来源很多，优先级大致是命令行参数 > Java 系统属性 > 操作系统环境变量 > 外部配置文件 > jar 内部配置文件 > 默认配置。配置文件方面 application.properties 优先于 application.yml，带 profile 的配置优先于默认配置，后加载的 profile 会覆盖前面的值。排错时可以用 --debug 查看条件评估报告。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Spring Boot 和 Spring', '校招', 'SpringBoot,Starter,自动配置', 2, 'Spring Boot 常见 Starter 有哪些？', '常见有 spring-boot-starter-web、spring-boot-starter-aop、spring-boot-starter-data-redis、spring-boot-starter-amqp、spring-boot-starter-data-elasticsearch、spring-boot-starter-validation、spring-boot-starter-test；第三方有 mybatis-plus-boot-starter、mybatis-spring-boot-starter 等。官方 Starter 命名通常是 spring-boot-starter-xxx，第三方通常是 xxx-spring-boot-starter。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '1-3 年', 'Nacos,配置中心,命名空间,分组,DataId', 3, 'Nacos 的分级存储模型是什么？', 'Nacos 用命名空间、组和配置集（DataId）三级组织配置。命名空间用于隔离环境或租户，组用于隔离同一环境下的业务模块，DataId 是具体配置项。通过 namespace + group + dataId 唯一定位一条配置，再配合集群和实例信息实现多环境、多集群管理。服务注册发现也使用命名空间和分组做隔离。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '1-3 年', 'Eureka,注册中心,服务发现,心跳', 3, 'Eureka 的服务注册与发现流程是怎样的？', '服务提供者启动时向 Eureka Server 注册实例信息，并定期发送心跳续约；Server 维护注册表，长时间收不到心跳会剔除实例。消费者从 Server 拉取服务列表并缓存，本地通过负载均衡选择实例调用；提供者下线时发送取消注册请求。Eureka 默认是 AP 模型，各节点通过复制保持最终一致。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '1-3 年', 'Nacos,Eureka,注册中心,对比', 3, 'Nacos 和 Eureka 有什么区别？', '两者都支持服务注册发现和心跳健康检查，默认都偏向 AP。Nacos 同时提供服务注册和配置管理，支持命名空间、分组、权重和推送更新，心跳和剔除更快；Eureka 只做注册中心，客户端定时拉取服务列表，生态更偏 Spring Cloud Netflix。新项目通常优先 Nacos，尤其是需要配置中心时。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '1-3 年', 'OpenFeign,服务调用,动态代理,负载均衡', 3, 'OpenFeign 的服务调用流程是怎样的？', '启动时扫描 @FeignClient 接口，生成动态代理并注册到 Spring 容器；调用接口方法时，代理根据注解和参数构造请求，通过 serviceId 从注册中心或负载均衡器获取实例，把逻辑服务名替换为具体 IP 和端口，最后用 HTTP 客户端发起请求并解码响应。超时、重试、拦截器和降级都可以在 Feign 层配置。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '1-3 年', 'SpringCloud,LoadBalancer,负载均衡,轮询,随机', 3, 'Spring Cloud LoadBalancer 有哪些负载均衡策略？', '默认提供 RoundRobinLoadBalancer 轮询和 RandomLoadBalancer 随机，Nacos 场景还有基于集群和权重的 NacosLoadBalancer。可以通过配置切换策略，也可以实现 ReactorServiceInstanceLoadBalancer 自定义。Ribbon 在 Spring Cloud 2020 之后已被 Spring Cloud LoadBalancer 取代。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '1-3 年', 'Hystrix,Sentinel,熔断,限流,服务保护', 3, 'Hystrix 和 Sentinel 有什么区别？', '两者都做熔断、限流和服务保护。Hystrix 主要基于线程池和信号量做隔离，强调熔断和降级，已停止维护；Sentinel 基于流量控制、熔断降级、系统自适应保护，提供控制台、热点参数限流、集群流控和更丰富的规则，生态更活跃。新项目通常选择 Sentinel 或 Resilience4j。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '3-5 年', 'Sentinel,限流,滑动窗口,QPS', 4, 'Sentinel 如何配置限流？滑动窗口算法是什么？', '引入 Sentinel 依赖并启动控制台，访问一次资源后在控制台配置 QPS 或线程数限流规则，也可以在代码中通过 FlowRuleManager 加载规则。滑动窗口把一段时间切成多个小桶，每个桶统计请求量，窗口随时间滑动并累加当前窗口内的计数，从而更平滑地判断是否超过阈值，避免固定窗口临界点突刺。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '1-3 年', 'Gateway,路由断言,过滤器,鉴权', 3, 'Spring Cloud Gateway 的路由断言和过滤器有哪些？', '断言用于匹配请求，常见有 Path、Method、Header、Query、Cookie、Host、After/Before/Between、RemoteAddr 等，可以组合使用。过滤器分 GatewayFilter 和 GlobalFilter，内置有 AddRequestHeader、AddRequestParameter、RewritePath、StripPrefix、SetStatus、AddResponseHeader、RequestRateLimiter 等；自定义过滤器可以实现鉴权、日志、灰度等逻辑。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '校招', 'MQ,异步,解耦,削峰', 2, '为什么要使用消息队列？有哪些应用场景？', 'MQ 主要解决异步、解耦和削峰。异步能把非核心流程从主链路剥离，缩短响应时间；解耦让生产者和消费者只依赖消息格式，新增消费者不影响生产者；削峰把突发流量缓冲到队列，保护下游。常见场景有订单通知、短信邮件、支付结果同步、日志收集、数据同步和秒杀。代价是系统复杂度、消息一致性和运维成本上升。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '3-5 年', 'RabbitMQ,消息可靠,Confirm,持久化,本地消息表', 4, 'RabbitMQ 如何保证发送消息可靠？', '生产者开启 publisher confirm 确认消息到达交换机，开启 return 回调处理路由失败；消息和交换机、队列都要持久化；发送失败时重试。对可靠性要求更高时，可以使用本地消息表：业务事务内写消息记录，定时任务扫描未发送消息重发，发送成功再更新状态。极端情况下还要考虑 broker 宕机和磁盘故障。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '3-5 年', 'RabbitMQ,消费可靠,ACK,重试,幂等', 4, 'RabbitMQ 如何保证消费消息可靠？', '使用手动 ACK，业务处理成功后再确认，失败则 nack 或拒绝；配置失败重试，超过次数投递死信队列；消费者要保证幂等，避免重复消费造成重复扣款或重复插入。还要处理消费者宕机导致消息未确认的情况，RabbitMQ 会在连接断开后重新投递。关键业务可以配合数据库唯一约束或状态机做兜底。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '1-3 年', 'RabbitMQ,死信队列,延迟队列,TTL', 3, '什么是死信队列和延迟队列？', '消息被拒绝且不重新入队、消息过期、队列满等情况下会变成死信，绑定死信交换机的队列就是死信队列，用于集中处理失败消息和告警。延迟队列是消息在指定时间后才被消费，RabbitMQ 可以通过 TTL + 死信交换机实现，也可以使用延迟插件；常见场景是订单超时取消、定时提醒。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '1-3 年', 'MQ,消息积压,扩容,消费能力', 3, '消息积压如何处理？', '先定位原因：消费者故障、消费逻辑变慢、流量突增还是分区不均。短期可以扩容消费者、提高并发和批量消费、优化慢 SQL 和外部调用；长期要评估分区数、消费能力和限流策略。若积压严重且允许丢弃，可以把旧消息转移到临时队列或设置 TTL；不能丢的消息要先恢复消费能力再逐步消化。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '校招', 'RabbitMQ,消息模式,Fanout,Direct,Topic', 2, 'RabbitMQ 有哪些常见消息模式？', '常见有简单队列（一个生产者一个消费者）、工作队列（多个消费者竞争消费）、发布订阅 Fanout（广播到所有绑定队列）、路由 Direct（按 routing key 精确匹配）、主题 Topic（routing key 支持 * 和 # 通配符）。还有 RPC 模式和 headers 模式。选型取决于是否需要广播、按规则路由还是竞争消费。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '3-5 年', '分布式,CAP,一致性,可用性,分区容错', 4, 'CAP 定理是什么？分布式系统如何取舍？', 'CAP 指一致性、可用性和分区容错性，分布式系统在网络分区发生时无法同时满足三者。由于网络分区不可避免，实际系统通常在 CP 和 AP 之间取舍：强一致场景选 CP，例如支付账务；高可用场景选 AP，例如商品展示、社交 feed，再通过最终一致性补偿。CAP 不是三选二那么简单，要结合业务和故障模型分析。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '1-3 年', '分布式,BASE,最终一致性,软状态', 3, 'BASE 理论是什么？', 'BASE 是对 CAP 中 AP 方向的工程化补充，包括基本可用、软状态和最终一致性。基本可用允许故障时降级或延迟响应；软状态允许存在中间状态；最终一致性指经过一段时间同步后数据达到一致。它适合高并发互联网业务，例如订单状态、缓存和消息最终一致，常配合重试、补偿和对账实现。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '3-5 年', '分布式事务,2PC,两阶段提交,强一致', 4, '二阶段提交（2PC）的流程和优缺点是什么？', '2PC 分准备和提交两个阶段：协调者先让所有参与者执行本地事务并投票，全部准备成功后再统一提交，否则统一回滚。优点是实现相对简单、能保证强一致；缺点是同步阻塞、协调者单点、参与者故障时可能长期锁资源，提交阶段部分参与者失败还会造成数据不一致。因此更适合短事务和强一致场景。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '3-5 年', 'Seata,分布式事务,AT,TCC,SAGA,XA', 4, 'Seata 有哪些分布式事务模式？', 'Seata 常见有 AT、TCC、SAGA 和 XA。AT 模式通过解析 SQL 生成前后镜像和 undo log，自动完成回滚，对业务侵入小；TCC 由业务实现 Try、Confirm、Cancel 三个方法，控制精细但开发量大；SAGA 用一系列本地事务和补偿动作处理长事务；XA 基于数据库 XA 协议，强一致但性能开销较大。选型要看一致性、侵入性和性能要求。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '3-5 年', '分布式事务,柔性事务,刚性事务,ACID,BASE', 4, '柔性事务和刚性事务有什么区别？', '刚性事务遵循 ACID，强调强一致和即时可见，典型是本地数据库事务和 2PC/XA；柔性事务遵循 BASE，允许中间状态和短暂不一致，通过重试、补偿、对账达到最终一致，典型是 TCC、SAGA、本地消息表和 MQ 最终一致。刚性事务实现简单但性能和可用性受限，柔性事务适合跨服务、高并发场景。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '1-3 年', '分布式锁,Redis,ZooKeeper,数据库', 3, '分布式锁有哪些使用场景和实现方案？', '常见场景是防止超卖、避免重复任务、保护共享资源和控制并发。实现方案有数据库唯一约束或 select for update、Redis 的 SET NX EX 和 Redisson、ZooKeeper 临时顺序节点。Redis 性能高，适合大多数高并发场景；ZooKeeper 基于 CP，可靠性更强但性能较低；数据库方案简单但并发能力弱。选型要结合一致性、性能和运维成本。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('微服务与消息队列', '3-5 年', '分布式锁,可重入,Redisson,分段锁', 4, '如何实现分布式锁的可重入？如何提升性能？', '可重入需要在锁中记录持有者标识和重入次数：同一线程再次加锁时计数加一，解锁时计数减一，计数为零才真正释放并删除锁。Redisson 的 RLock 已经封装了可重入和看门狗续期。提升性能可以缩小锁粒度、缩短持锁时间、使用分段锁、读写分离或把库存扣减放到 Redis/Lua 原子操作中，避免所有请求争同一把锁。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Redis 和缓存', '1-3 年', 'Redis,主从集群,分片集群,Cluster,哈希槽', 3, 'Redis 主从集群和分片集群有什么区别？', '主从集群是一主多从，主节点处理写，从节点复制数据并分担读，配合 Sentinel 做故障转移，主要解决可用性和读扩展；分片集群把数据按槽位分散到多个主节点，每个主节点再带从节点，解决单机内存和写并发的横向扩展问题。Redis Cluster 使用 16384 个哈希槽，客户端根据 key 路由到对应节点。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Redis 和缓存', '1-3 年', 'Redis,过期键,惰性删除,定期删除', 3, 'Redis 的过期键删除策略是什么？', 'Redis 采用惰性删除加定期删除。惰性删除是在访问 key 时才检查是否过期，过期就删除；定期删除是周期性随机抽样一部分设置了过期时间的 key，删除其中过期的。两种策略配合在 CPU 和内存之间折中，避免每次遍历所有 key。内存不足时还会触发淘汰策略。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Redis 和缓存', '3-5 年', 'Redis,红锁,RedLock,分布式锁', 4, '什么是 Redis 红锁？为什么不推荐使用？', 'RedLock 是 Redis 官方提出的一种分布式锁算法：客户端依次向多个独立 Redis 主节点加锁，只有在大多数节点加锁成功且总耗时小于锁有效期时才认为成功。它能降低单主节点故障导致锁失效的风险，但实现复杂，依赖时钟和网络假设，争议较大；Redisson 的红锁实现也不能保证锁落在不同 master 上，生产环境通常优先使用单实例或主从加哨兵的普通 Redisson 锁。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('Redis 和缓存', '1-3 年', 'Redis,高可用,哨兵,降级,持久化', 3, 'Redis 宕机后数据如何处理？', '如果部署了主从加 Sentinel 或 Cluster，主节点故障会自动故障转移，业务短暂重连后恢复；如果 Redis 整体不可用，可以降级直接查数据库，或使用本地缓存 Caffeine 兜底，避免请求全部打穿到数据库。恢复后要评估数据丢失：RDB 可能丢一段时间的数据，AOF everysec 最多丢约一秒，关键数据不能只依赖缓存，必须有数据库或消息补偿。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('常用组件', '校招', 'Nginx,正向代理,反向代理', 2, '什么是正向代理和反向代理？', '正向代理代理客户端，客户端把请求发给代理，由代理访问目标服务器，目标服务器不知道真实客户端，常用于科学上网、访问受限资源和隐藏客户端；反向代理代理服务器，客户端访问代理，代理把请求转发给内部服务，客户端不知道真实服务器，常用于负载均衡、SSL 卸载、缓存和安全防护。Nginx 通常作为反向代理。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('常用组件', '校招', 'CDN,缓存,边缘节点,静态资源', 2, 'CDN 的原理和作用是什么？', 'CDN 把静态资源缓存到离用户更近的边缘节点，用户请求时通过 DNS 调度到最近节点，命中缓存直接返回，未命中再回源。它能降低访问延迟、分担源站压力、提高可用性，并具备一定的 DDoS 防护能力。静态资源通常配合内容哈希和长缓存，HTML 和动态接口则要谨慎缓存。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('常用组件', '1-3 年', 'Nginx,负载均衡,upstream,权重', 3, 'Nginx 如何实现负载均衡？', '在 upstream 中配置后端服务器列表，proxy_pass 指向 upstream。默认是轮询；可以用 weight 设置权重，ip_hash 让同一客户端固定到同一台机器，least_conn 选择连接数最少的节点，还可以使用 hash 做一致性哈希。配合健康检查、超时和重试策略，提高后端集群的可用性。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('常用组件', '1-3 年', 'Nginx,限流,limit_req,burst', 3, 'Nginx 如何限流？', '使用 limit_req_zone 定义限流区域，按客户端 IP 等 key 统计请求速率，例如 rate=10r/s；在 location 中用 limit_req 应用规则，burst 允许突发请求，nodelay 表示突发请求立即处理而不是排队。还可以用 limit_conn 限制并发连接数。限流阈值要结合压测和业务峰值设置，避免误伤正常用户。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('常用组件', '1-3 年', 'Elasticsearch,倒排索引,分词,全文检索', 3, '什么是倒排索引？为什么 ES 搜索快？', '正排索引是文档 ID 到文档内容的映射；倒排索引反过来，记录每个词条出现在哪些文档、位置和频次，形成词条到文档 ID 的映射。搜索时先对查询分词，找到词条对应的文档列表，再做合并、打分和排序。因为不需要逐篇扫描全文，ES 在海量文本检索上比 MySQL 的 like 快得多。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('常用组件', '3-5 年', 'Elasticsearch,索引文档,分片,refresh,translog', 4, 'ES 索引文档的过程是怎样的？', '客户端把 JSON 文档发给协调节点，协调节点根据文档 ID 计算路由，转发到对应主分片；主分片写入内存缓冲和 translog，并同步复制到副本分片；默认每秒 refresh 一次，把内存缓冲生成新的 segment，使文档可被搜索；translog 保证故障恢复，后续再 flush 到磁盘并合并 segment。Near real-time 的“近实时”就来自 refresh 机制。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('常用组件', '3-5 年', 'Elasticsearch,搜索流程,查询阶段,取回阶段,深度分页', 4, 'ES 的搜索流程是怎样的？', '搜索分查询阶段和取回阶段。查询阶段由协调节点把请求广播到所有相关分片，各分片在本地执行查询并返回文档 ID 和排序值；协调节点合并、排序并选出要返回的文档；取回阶段再根据文档 ID 到对应分片获取完整文档，最后返回给客户端。深度分页会带来大量协调开销，所以要用 search_after 或滚动查询。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('常用组件', '1-3 年', 'Elasticsearch,MySQL,全文检索,最终一致', 3, 'ES 和 MySQL 有什么区别？分别适合什么场景？', 'MySQL 擅长事务、强一致、结构化数据和关联查询，适合订单、账户、库存等核心业务数据；ES 擅长全文检索、分词、相关性打分、聚合分析和海量日志搜索，但不支持事务，近实时而非实时。实际系统常用 MySQL 存权威数据，通过 Canal、MQ 或业务双写同步到 ES 做搜索和分析，并接受最终一致。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('常用组件', '3-5 年', 'Elasticsearch,集群,分片,副本,reindex', 4, 'ES 集群和分片如何设计？', '一个索引由多个主分片和副本分片组成，主分片数在创建后不能直接修改，副本数可以调整。分片过多会增加集群元数据和协调开销，过少则无法充分利用节点。设计时要估算数据量、增长趋势、单分片大小和查询并发，通常让单分片控制在几十 GB 级别，并结合节点数设置副本；数据量增长时可以新建索引再 reindex。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('常用组件', '校招', 'Docker,虚拟机,容器,隔离', 2, 'Docker 和虚拟机有什么区别？', '虚拟机通过 Hypervisor 虚拟化硬件，每台虚拟机有独立操作系统，隔离性强但启动慢、资源占用高；Docker 容器共享宿主机内核，只打包应用和依赖，启动快、体积小、密度高。容器隔离性弱于虚拟机，安全性要求高的多租户场景要结合命名空间、cgroups 和安全配置。两者可以结合使用，例如在虚拟机中运行容器。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('常用组件', '校招', 'Docker,镜像,容器,分层存储', 2, 'Docker 镜像和容器有什么区别？', '镜像是只读模板，包含应用代码、运行时、依赖和配置，采用分层存储；容器是镜像的运行实例，在镜像层之上加一个可写层，可以启动、停止、删除。一个镜像可以启动多个容器，容器删除后可写层数据默认丢失，需要持久化的数据要用数据卷或绑定挂载。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('常用组件', '校招', 'Docker,数据卷,持久化,挂载', 2, 'Docker 数据卷的作用是什么？', '数据卷用于持久化和共享容器数据，生命周期独立于容器，删除容器后卷仍然存在。它可以把容器内目录挂载到宿主机或命名卷，方便备份、迁移和多个容器共享；相比直接写容器可写层，卷的性能和可管理性更好。常见用法是数据库数据目录、上传文件和配置文件。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('常用组件', '1-3 年', 'Docker,网络模式,bridge,host,none', 3, 'Docker 有哪些默认网络模式？', '常见默认网络模式有 bridge、host 和 none。bridge 是默认模式，容器有独立网络命名空间，通过虚拟网桥与宿主机通信，端口需要映射；host 模式容器与宿主机共享网络命名空间，性能好但端口冲突风险高；none 模式只有 loopback，不配置外部网络。多容器项目通常自定义 bridge 网络，通过服务名互相访问。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('常用组件', '校招', 'Docker,Compose,YAML,多容器', 2, '什么是 Docker Compose？', 'Docker Compose 用一个 YAML 文件定义多个服务、网络、数据卷和环境变量，通过 docker compose up 一条命令启动整套应用，down 停止并清理。它适合本地开发和单机多容器编排，能描述服务依赖、端口映射、健康检查和构建上下文；生产环境大规模集群通常使用 Kubernetes。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('常用组件', '1-3 年', 'Git,工作区,暂存区,版本库', 2, 'Git 工作区、暂存区和版本库有什么关系？', '工作区是当前看到的项目目录；暂存区是 .git/index，保存下一次提交要包含的修改；版本库是 .git 目录，保存提交历史、分支和对象。git add 把工作区修改放入暂存区，git commit 把暂存区内容生成一个提交写入版本库，git checkout/restore 可以在三者之间恢复文件。理解这三个区域是排查 Git 状态的基础。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('常用组件', '校招', 'Git,冲突,merge,rebase', 2, 'Git 冲突如何解决？', '先 git status 查看冲突文件，打开文件找到 <<<<<<<、=======、>>>>>>> 标记，结合业务与同事沟通，保留正确内容并删除标记；然后 git add 标记已解决，全部解决后 git commit 完成合并。冲突较多时可以用 git mergetool 或 IDE 的三方合并工具。预防冲突要小步提交、频繁拉取、按模块拆分分支。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('常用组件', '1-3 年', 'Git,分支管理,GitFlow,hotfix', 3, '项目中 Git 分支如何管理？', '常见模型是 main/master 保持可发布，develop 集成日常开发，功能分支 feature/xxx 从 develop 拉出，完成后合并回去；发布用 release 分支，线上紧急修复用 hotfix 分支，修完同时合并回 main 和 develop。分支命名要见名知意，提交要小而清晰，合并前跑测试和代码评审。团队也可以采用 trunk-based 或 Git Flow 的简化版。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('常用组件', '校招', 'Maven,依赖管理,目录结构,pom', 2, 'Maven 的作用是什么？标准目录结构是怎样的？', 'Maven 是 Java 项目管理工具，负责依赖管理、项目构建、测试、打包、发布和项目信息管理，遵循约定优于配置。标准结构是 src/main/java 放源码，src/main/resources 放配置，src/test/java 放测试代码，src/test/resources 放测试配置，target 放编译产物，pom.xml 描述项目坐标、依赖和插件。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('常用组件', '1-3 年', 'Maven,生命周期,clean,package,install', 3, 'Maven 的生命周期有哪些阶段？', 'Maven 有三套生命周期：clean 负责清理，default/build 负责构建，site 负责生成站点。default 常用阶段依次是 validate、compile、test、package、verify、install、deploy；执行某个阶段会自动执行它前面的阶段。install 把构件安装到本地仓库，deploy 发布到远程仓库。插件目标绑定到阶段上执行具体任务。', '网络整理-2026-10-28-黑马面试题', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
