
SELECT
    t.id,
    q.id,
    0,
    115,
    1,
    CURRENT_TIMESTAMP(3),
    CURRENT_TIMESTAMP(3)
FROM question_bank q
JOIN interview_track t ON t.code = 'java-backend-campus'
WHERE q.source = '网络整理-2026-10-28-黑马面试题'
  AND q.status = 'ACTIVE'
  AND q.deleted = 0;

