SELECT
    t.id,
    q.id,
    0,
    110,
    1,
    CURRENT_TIMESTAMP(3),
    CURRENT_TIMESTAMP(3)
FROM question_bank q
JOIN interview_track t ON t.code = 'java-microservices'
WHERE q.source = '网络整理-2026-10-28-黑马面试题'
  AND q.status = 'ACTIVE'
  AND q.deleted = 0
  AND q.category IN (
      'Java 基础', 'Java 并发', 'Spring Boot 和 Spring',
      'MySQL 和 MyBatis', 'Redis 和缓存', '微服务与消息队列', '常用组件'
  );
